from fastapi import FastAPI,HTTPException
from fastapi.responses import HTMLResponse
from pydantic import BaseModel,Field
from .pipeline import Pipeline
from .config import settings
app=FastAPI(title="CFB Deep Run",version="2.1");pipe=Pipeline()
class Req(BaseModel): team_a:str=Field(min_length=2);team_b:str=Field(min_length=2)
@app.get("/health")
async def health():return {"ok":True,"version":"2.1","api_configured":bool(settings.api_key)}
@app.post("/deep-run")
async def deep(r:Req):
 if not settings.api_key:raise HTTPException(503,"CFBD_API_KEY is not configured.")
 a,b=r.team_a.strip(),r.team_b.strip()
 if a.casefold()==b.casefold():raise HTTPException(400,"Choose two different teams.")
 try:return await pipe.run(a,b,settings.season)
 except Exception as e:raise HTTPException(502,str(e))
@app.get("/",response_class=HTMLResponse)
async def ui():
 return """<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>CFB Deep Run</title><style>body{margin:0;background:#07101d;color:#f7f9ff;font-family:-apple-system,system-ui}.w{max-width:780px;margin:auto;padding:25px 16px}.hero{text-align:center}.card{background:#101d30;border:1px solid #263a58;border-radius:20px;padding:18px;margin:14px 0}.e{display:grid;grid-template-columns:1fr 35px 1fr;gap:8px;align-items:center}input{width:100%;box-sizing:border-box;padding:15px;background:#07101d;border:1px solid #3a4d69;border-radius:12px;color:white;font-size:17px}.vs{text-align:center}button{width:100%;margin-top:12px;padding:16px;border:0;border-radius:12px;background:#4f8cff;color:white;font-weight:900}.score{display:grid;grid-template-columns:1fr auto 1fr;text-align:center;align-items:center}.pts{font-size:58px;font-weight:900}.win{color:#46d998}.m{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.box,.factor{background:#07101d;border-radius:12px;padding:12px;margin-top:8px}.box{text-align:center}.box b{display:block;font-size:20px}.small{color:#9babc1;font-size:12px}.hidden{display:none}@media(max-width:600px){.e{grid-template-columns:1fr}.vs{display:none}.m{grid-template-columns:1fr 1fr}}</style></head><body><main class="w"><div class="hero"><div style="font-size:40px">🏈</div><h1>CFB Deep Run</h1><p class="small">Two teams. One clear prediction.</p></div><div class="card"><div class="e"><input id="a" placeholder="Team 1"><div class="vs">VS</div><input id="b" placeholder="Team 2"></div><button id="run">RUN DEEP ANALYSIS</button><p id="status" class="small" style="text-align:center">Ready.</p></div><div id="r" class="card hidden"><div class="score"><div><b id="ta"></b><div id="sa" class="pts"></div><div id="wa" class="win"></div></div><div>—</div><div><b id="tb"></b><div id="sb" class="pts"></div><div id="wb" class="win"></div></div></div><div class="m"><div class="box"><b id="spread"></b><span class="small">PROJECTED SPREAD</span></div><div class="box"><b id="total"></b><span class="small">PROJECTED TOTAL</span></div><div class="box"><b id="conf"></b><span class="small">CONFIDENCE</span></div></div><h3>Why the model sees it this way</h3><div id="f"></div><p class="small">Matchup explanations are shown instead of raw model numbers. Missing data lowers confidence rather than being guessed.</p></div></main><script>const $=x=>document.getElementById(x);$("run").onclick=async()=>{let a=$("a").value.trim(),b=$("b").value.trim();if(!a||!b)return;$("status").textContent="Running 50,000 simulations…";try{let q=await fetch("/deep-run",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({team_a:a,team_b:b})}),j=await q.json();if(!q.ok)throw Error(j.detail);let p=j.prediction,n=Object.keys(p.score);$("ta").textContent=n[0];$("tb").textContent=n[1];$("sa").textContent=Math.round(p.score[n[0]]);$("sb").textContent=Math.round(p.score[n[1]]);$("wa").textContent=Math.round(100*p.simulation_win_probability[n[0]])+"% win";$("wb").textContent=Math.round(100*p.simulation_win_probability[n[1]])+"% win";$("spread").textContent=(p.margin>=0?n[0]:n[1])+" "+Math.abs(p.margin).toFixed(1);$("total").textContent=Number(p.total).toFixed(1);$("conf").textContent=j.confidence.label;$("f").innerHTML=j.top_factors.map(x=>`<div class="factor"><b>${x.title}</b><div class="small">${x.summary}</div></div>`).join("");$("r").classList.remove("hidden");$("status").textContent="Deep Run complete."}catch(e){$("status").textContent=e.message}};</script></body></html>"""
